import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the curve in the plane defined by y^2 + 2*({p_num}/{p_den})*x*y + {q}|x - {h}| = {r}. The graph of this curve partitions the plane into regions. What is the area of the bounded region enclosed by this curve?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We enforce p = p_num/p_den = 1/t for integer t >= 3, so p != 1.
# Choose q even so that the area becomes an integer: area = q^2 * t^3 / 2.
for _ in range(200):
    p_num = rng.randint(2, 9)
    t = rng.randint(3, 5)  # ensures p <= 1/3 and increases difficulty
    p_den = p_num * t
    # q even in a moderate range
    q = 2 * rng.randint(3, 17)  # q in {6,8,...,34}
    # nonzero horizontal shift to break symmetry
    h = rng.choice([rng.randint(-20, -1), rng.randint(1, 20)])
    # compute r = q^2 * t^2 / 4 (integer since q is even)
    r = (q * q * t * t) // 4
    # compute area = q^2 * t^3 / 2
    area = (q * q * t * t * t) // 2
    # sanity checks to keep instances nontrivial and bounded
    if p_den % p_num != 0:
        continue
    if area < 200 or area > 100000:
        continue
    if r <= 0:
        continue
    return {"p_num": p_num, "p_den": p_den, "q": q, "h": h, "r": r}
# Fallback deterministic instance (guaranteed valid)
p_num = 3
t = 4
p_den = p_num * t
q = 14
h = 7
r = (q * q * t * t) // 4
return {"p_num": p_num, "p_den": p_den, "q": q, "h": h, "r": r}

    def verifier(assign):
# Validate types and compute the correct answer. Enforce difficulty constraints.
try:
    p_num = int(assign.get("p_num"))
    p_den = int(assign.get("p_den"))
    q = int(assign.get("q"))
    h = int(assign.get("h"))
    r = int(assign.get("r"))
except Exception:
    # Invalid typing
    return (False, None)
# Domain checks
if p_num <= 0 or p_den <= 0:
    # p must be positive
    return (False, None)
if p_den % p_num != 0:
    # We require p = 1/t with integer t to ensure integrality and intended structure
    return (False, None)
t = p_den // p_num
if t < 3:
    # Enforce p <= 1/3 for increased difficulty (avoid seed-like p=1)
    return (False, None)
if h == 0:
    # Nonzero shift for asymmetry and extra casework
    return (False, None)
if q % 2 != 0 or q <= 0:
    # q must be even and positive to keep r, area integral
    return (False, None)
# Check that r matches the design r = q^2 * t^2 / 4
expected_r = (q * q * t * t) // 4
if expected_r != r:
    # Provided r must be consistent with parameters
    return (False, None)
# Compute the area: A = q^2 * t^3 / 2
area_numer = q * q * t * t * t
if area_numer % 2 != 0:
    # Should not happen with q even
    return (False, None)
answer = area_numer // 2
# Extra sanity bounds
if answer < 200 or answer > 100000:
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

